\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":1295,\"bb\":568043,\"url_path\":\"/en/library/bg/4/5/devanagari/\",\"body_final\":\"श्रीभगवानुवाच
बहूनि मे व्यतीतानि जन्मानि तव चार्जुन ।
तान्यहं वेद सर्वाणि न त्वं वेत्थ परन्तप ॥ ५ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":1296,\"bb\":1154,\"url_path\":\"/en/library/bg/4/5/b1154/\",\"body_value\":\"śrī-bhagavān uvāca
bahūni me vyatītāni
janmāni tava cārjuna
tāny ahaṁ veda sarvāṇi
na tvaṁ vettha paran-tapa\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":1297,\"bb\":1155,\"url_path\":\"/en/library/bg/4/5/b1155/\",\"shadow_value\":\"śrī-bhagavān uvāca – the Personality of Godhead said; bahūni – many; me – of Mine; vyatītāni – have passed; janmāni – births; tava – of yours; ca – and also; arjuna – O Arjuna; tāni – those; aham – I; veda – do know; sarvāṇi – all; na – not; tvam – you; vettha – know; param-tapa – O subduer of the enemy.\",\"word_for_word_value\":[{\"word\":\"śrī-bhagavān uvāca\",\"translation\":\"the Personality of Godhead said\"},{\"word\":\"bahūni\",\"translation\":\"many\"},{\"word\":\"me\",\"translation\":\"of Mine\"},{\"word\":\"vyatītāni\",\"translation\":\"have passed\"},{\"word\":\"janmāni\",\"translation\":\"births\"},{\"word\":\"tava\",\"translation\":\"of yours\"},{\"word\":\"ca\",\"translation\":\"and also\"},{\"word\":\"arjuna\",\"translation\":\"O Arjuna\"},{\"word\":\"tāni\",\"translation\":\"those\"},{\"word\":\"aham\",\"translation\":\"I\"},{\"word\":\"veda\",\"translation\":\"do know\"},{\"word\":\"sarvāṇi\",\"translation\":\"all\"},{\"word\":\"na\",\"translation\":\"not\"},{\"word\":\"tvam\",\"translation\":\"you\"},{\"word\":\"vettha\",\"translation\":\"know\"},{\"word\":\"param-tapa\",\"translation\":\"O subduer of the enemy\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":1298,\"bb\":1156,\"url_path\":\"/en/library/bg/4/5/b1156/\",\"body_value\":\"The Personality of Godhead said: Many, many births both you and I have passed. I can remember all of them, but you cannot, O subduer of the enemy!\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":1299,\"bb\":1157,\"url_path\":\"/en/library/bg/4/5/b1157/\",\"body_value\":\"In the Brahma-saṁhitā (5.33) we have information of many, many incarnations of the Lord. It is stated there:\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":1300,\"bb\":1158,\"url_path\":\"/en/library/bg/4/5/b1158/\",\"body_value\":\"advaitam acyutam anādim ananta-rūpam
ādyaṁ purāṇa-puruṣaṁ nava-yauvanaṁ ca
vedeṣu durlabham adurlabham ātma-bhaktau
govindam ādi-puruṣaṁ tam ahaṁ bhajāmi\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":1301,\"bb\":1159,\"url_path\":\"/en/library/bg/4/5/b1159/\",\"body_value\":\"“I worship the Supreme Personality of Godhead, Govinda [Kṛṣṇa], who is the original person – absolute, infallible, without beginning. Although expanded into unlimited forms, He is still the same original, the oldest, and the person always appearing as a fresh youth. Such eternal, blissful, all-knowing forms of the Lord are usually not understood by even the best Vedic scholars, but they are always manifest to pure, unalloyed devotees.”\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":1302,\"bb\":1160,\"url_path\":\"/en/library/bg/4/5/b1160/\",\"body_value\":\"It is also stated in Brahma-saṁhitā (5.39):\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":1303,\"bb\":1161,\"url_path\":\"/en/library/bg/4/5/b1161/\",\"body_value\":\"rāmādi-mūrtiṣu kalā-niyamena tiṣṭhan
nānāvatāram akarod bhuvaneṣu kintu
kṛṣṇaḥ svayaṁ samabhavat paramaḥ pumān yo
